# Реализуйте ротацию пары Access + Refresh токенов с одноразовым jti и Blacklist
import uuid

class TokenRotationService:
    def __init__(self):
        self._revoked_jti: set[str] = set()

    def issue_pair(self, user_id: int) -> dict[str, dict]:
        return {
            "access": {"sub": user_id, "typ": "access", "jti": str(uuid.uuid4())},
            "refresh": {"sub": user_id, "typ": "refresh", "jti": str(uuid.uuid4())},
        }

    def refresh_tokens(self, refresh_payload: dict) -> dict[str, dict]:
        if refresh_payload.get("typ") != "refresh":
            raise PermissionError("Для обновления пары требуется именно refresh-токен")
        jti = refresh_payload["jti"]
        if jti in self._revoked_jti:
            raise PermissionError("Refresh-токен уже был использован или отозван!")
        # Отзываем использованный refresh-токен (Token Rotation)
        self._revoked_jti.add(jti)
        return self.issue_pair(refresh_payload["sub"])

