class PatchModel:
    _defaults = {"name": None, "role": "user", "active": True}
    _aliases = {"name": "fullName", "active": "isActive"}

    def __init__(self, **kwargs):
        self._fields_set = set()
        self._values = dict(self._defaults)
        for k, v in kwargs.items():
            if k not in self._defaults:
                raise ValueError(f"Unknown field: {k}")
            self._values[k] = v
            self._fields_set.add(k)

    def model_dump(self, exclude_unset=False, exclude_none=False, by_alias=False) -> dict:
        res = {}
        for k, v in self._values.items():
            if exclude_unset and k not in self._fields_set:
                continue
            if exclude_none and v is None:
                continue
            out_key = self._aliases.get(k, k) if by_alias else k
            res[out_key] = v
        return res

