import re

_PARAM_RE = re.compile(r"^\{[^/]+\}$")

def find_route_conflicts(routes: list) -> list:
    counts = {}
    for method, path in routes:
        segs = [s for s in path.split("/") if s]
        canon_segs = ["{}" if _PARAM_RE.match(s) else s for s in segs]
        canon_path = "/" + "/".join(canon_segs) if canon_segs else "/"
        key = (method.upper(), canon_path)
        counts[key] = counts.get(key, 0) + 1
    return sorted(k for k, cnt in counts.items() if cnt > 1)

