import inspect

class RequestDispatcher:
    def __init__(self, pool_capacity: int = 2):
        self.pool_capacity = pool_capacity
        self.active_threads = 0
        self.loop_calls = 0
        self.pool_calls = 0

    def dispatch(self, fn, *args, hold=False):
        if inspect.iscoroutinefunction(fn):
            self.loop_calls += 1
            coro = fn(*args)
            try:
                coro.send(None)
            except StopIteration as stop:
                return {"mode": "event_loop", "result": stop.value}
            finally:
                coro.close()
        if self.active_threads >= self.pool_capacity:
            raise RuntimeError("ThreadPool exhausted")
        self.active_threads += 1
        self.pool_calls += 1
        try:
            res = fn(*args)
            return {"mode": "thread_pool", "result": res}
        finally:
            if not hold:
                self.active_threads -= 1

    def release_thread(self):
        if self.active_threads > 0:
            self.active_threads -= 1

