def bulk_import(records: list, batch_size: int, db) -> dict:
    size = max(1, batch_size)
    inserted = 0
    failed_batches = 0
    for i in range(0, len(records), size):
        batch = records[i:i + size]
        try:
            db.insert_batch(batch)
            db.commit()
            inserted += len(batch)
        except Exception:
            db.rollback()
            failed_batches += 1
    return {"inserted": inserted, "failed_batches": failed_batches, "round_trips": db.round_trips}

