class FakeDB:
    def __init__(self, bad_val=None):
        self.committed = []
        self.staged = []
        self.round_trips = 0
        self.bad_val = bad_val
    def insert_batch(self, batch):
        self.round_trips += 1
        if self.bad_val in batch:
            raise ValueError("bad record")
        self.staged.extend(batch)
    def commit(self):
        self.committed.extend(self.staged)
        self.staged.clear()
    def rollback(self):
        self.staged.clear()
db1 = FakeDB()
res1 = bulk_import(list(range(20)), batch_size=5, db=db1)
assert res1 == {"inserted": 20, "failed_batches": 0, "round_trips": 4}
assert res1["round_trips"] < 20 and db1.committed == list(range(20))
db2 = FakeDB(bad_val=7)
res2 = bulk_import(list(range(15)), batch_size=5, db=db2)
assert res2 == {"inserted": 10, "failed_batches": 1, "round_trips": 3}
assert db2.committed == [0, 1, 2, 3, 4, 10, 11, 12, 13, 14]
assert db2.round_trips == 3

